using System;using System.Security.Cryptography;using BeamScheduleFormatter;
class AccessProtocolTests{static int checks;static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}static void Main(){using(var rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;string key=rsa.ToXmlString(true),pub=rsa.ToXmlString(false),request=AccessCodes.NewRequest();for(int apps=1;apps<=7;apps++){string code=AccessCodes.Generate(request,key,apps);Check(AccessCodes.Verify(request,code,pub),"Signed selection rejected");var p=code.Split('.');p[3]=apps==7?"1":"7";Check(!AccessCodes.Verify(request,string.Join(".",p),pub),"App selection tampering accepted");Check(!AccessCodes.Verify(AccessCodes.NewRequest(),code,pub),"Wrong request accepted");Check(!AccessCodes.Verify(request,AccessCodes.GenerateAt(request,key,DateTime.UtcNow.AddHours(-9),apps),pub),"Expired code accepted");}bool rejected=false;try{AccessCodes.Generate(request,key,0);}catch{rejected=true;}Check(rejected,"No-app approval accepted");}TimeSpan clock=TimeSpan.Zero;var lease=new AccessLease(()=>clock);lease.Start();Check(lease.IsValid,"Fresh lease");clock=TimeSpan.FromHours(8);Check(!lease.IsValid,"Eight-hour expiry");Console.WriteLine("PASS: "+checks+" signed app selection, request binding, tamper rejection and expiry checks. Ephemeral test keys only.");}}
